        # pre1 and pre2 are None or list of strings
        # A version without pre-release sorts after one with
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release is greater
        if pre2 is None:
            return -1  # version with pre-release is less

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric, compare numerically
                num1, num2 = int(id1), int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    def sort_key(v):
        major, minor, patch, prerelease_ids = parse_version(v)

        # For sorting: (major, minor, patch, prerelease_tuple)
        # We need to handle pre-release comparison carefully
        # Pre-release versions sort before release versions

        if prerelease_ids is None:
            # Release version: sort after pre-release, use infinity for pre-release part
            return (major, minor, patch, (1,))  # 1 for release, 0 for pre-release
        else:
            # Pre-release version
            # Convert identifiers to comparable tuples
            pre_tuple = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    # Numeric identifier: (0, number) - 0 sorts before 1
                    pre_tuple.append((0, int(identifier)))
                else:
                    # Non-numeric identifier: (1, string) - sorts after numeric
                    pre_tuple.append((1, identifier))
            return (major, minor, patch, (0, tuple(pre_tuple)))

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

